ALTER TABLE public.products ADD COLUMN IF NOT EXISTS education_meta jsonb NOT NULL DEFAULT '{}'::jsonb;
CREATE TABLE public.academy_lessons (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), module_id uuid NOT NULL REFERENCES public.product_modules(id) ON DELETE CASCADE, title text NOT NULL, body text NOT NULL DEFAULT '', objectives text NOT NULL DEFAULT '', references_text text NOT NULL DEFAULT '', minutes integer NOT NULL DEFAULT 10 CHECK(minutes>0), order_index integer NOT NULL DEFAULT 0, published boolean NOT NULL DEFAULT false, version integer NOT NULL DEFAULT 1);
GRANT SELECT,INSERT,UPDATE,DELETE ON public.academy_lessons TO authenticated; GRANT ALL ON public.academy_lessons TO service_role;
ALTER TABLE public.academy_lessons ENABLE ROW LEVEL SECURITY;
CREATE POLICY lessons_read ON public.academy_lessons FOR SELECT TO authenticated USING(private.has_role(auth.uid(),'admin') OR (published AND EXISTS(SELECT 1 FROM public.product_modules m WHERE m.id=module_id AND private.has_product_access(auth.uid(),m.product_id))));
CREATE POLICY lessons_admin ON public.academy_lessons FOR ALL TO authenticated USING(private.has_role(auth.uid(),'admin')) WITH CHECK(private.has_role(auth.uid(),'admin'));
CREATE TABLE public.academy_questions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), lesson_id uuid NOT NULL REFERENCES public.academy_lessons(id) ON DELETE CASCADE, prompt text NOT NULL, options jsonb NOT NULL DEFAULT '[]', answer_index integer NOT NULL, explanation text NOT NULL, kind text NOT NULL DEFAULT 'choice', tolerance numeric NOT NULL DEFAULT 0);
GRANT SELECT,INSERT,UPDATE,DELETE ON public.academy_questions TO authenticated; GRANT ALL ON public.academy_questions TO service_role;
ALTER TABLE public.academy_questions ENABLE ROW LEVEL SECURITY;
CREATE POLICY questions_admin ON public.academy_questions FOR ALL TO authenticated USING(private.has_role(auth.uid(),'admin')) WITH CHECK(private.has_role(auth.uid(),'admin'));
CREATE TABLE public.academy_progress (user_id uuid NOT NULL, lesson_id uuid NOT NULL REFERENCES public.academy_lessons(id), score numeric NOT NULL CHECK(score>=0 AND score<=100), completed_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(user_id,lesson_id));
GRANT SELECT ON public.academy_progress TO authenticated; GRANT ALL ON public.academy_progress TO service_role;
ALTER TABLE public.academy_progress ENABLE ROW LEVEL SECURITY;
CREATE POLICY progress_read ON public.academy_progress FOR SELECT TO authenticated USING(user_id=auth.uid() OR private.has_role(auth.uid(),'admin'));
CREATE TABLE public.academy_attempts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, lesson_id uuid NOT NULL REFERENCES public.academy_lessons(id), score numeric NOT NULL, answers jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.academy_attempts TO authenticated; GRANT ALL ON public.academy_attempts TO service_role;
ALTER TABLE public.academy_attempts ENABLE ROW LEVEL SECURITY;
CREATE POLICY attempts_read ON public.academy_attempts FOR SELECT TO authenticated USING(user_id=auth.uid() OR private.has_role(auth.uid(),'admin'));
CREATE TABLE public.academy_xp(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, event_key text NOT NULL, amount integer NOT NULL CHECK(amount>0), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(user_id,event_key));
GRANT SELECT ON public.academy_xp TO authenticated; GRANT ALL ON public.academy_xp TO service_role;
ALTER TABLE public.academy_xp ENABLE ROW LEVEL SECURITY;
CREATE POLICY xp_read ON public.academy_xp FOR SELECT TO authenticated USING(user_id=auth.uid() OR private.has_role(auth.uid(),'admin'));
CREATE TABLE public.academy_certificates(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, product_id uuid NOT NULL REFERENCES public.products(id), version integer NOT NULL DEFAULT 1, student_name text NOT NULL, course_title text NOT NULL, hours numeric NOT NULL, score numeric NOT NULL, code uuid NOT NULL DEFAULT gen_random_uuid() UNIQUE, issued_at timestamptz NOT NULL DEFAULT now(), invalidated_reason text, UNIQUE(user_id,product_id,version));
GRANT SELECT ON public.academy_certificates TO authenticated; GRANT ALL ON public.academy_certificates TO service_role;
ALTER TABLE public.academy_certificates ENABLE ROW LEVEL SECURITY;
CREATE POLICY certificates_read ON public.academy_certificates FOR SELECT TO authenticated USING(user_id=auth.uid() OR private.has_role(auth.uid(),'admin'));
CREATE TABLE public.academy_reading(user_id uuid NOT NULL, product_id uuid NOT NULL REFERENCES public.products(id), page integer NOT NULL DEFAULT 1 CHECK(page>0), bookmarks jsonb NOT NULL DEFAULT '[]', updated_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(user_id,product_id));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.academy_reading TO authenticated; GRANT ALL ON public.academy_reading TO service_role;
ALTER TABLE public.academy_reading ENABLE ROW LEVEL SECURITY;
CREATE POLICY reading_own ON public.academy_reading FOR ALL TO authenticated USING(user_id=auth.uid() AND private.has_product_access(auth.uid(),product_id)) WITH CHECK(user_id=auth.uid() AND private.has_product_access(auth.uid(),product_id));
CREATE OR REPLACE FUNCTION private.academy_can_study(_lesson uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.academy_lessons l JOIN public.product_modules m ON m.id=l.module_id JOIN public.products p ON p.id=m.product_id WHERE l.id=_lesson AND l.published AND (private.has_role(auth.uid(),'admin') OR (p.status='active' AND private.has_product_access(auth.uid(),p.id))) AND NOT EXISTS(SELECT 1 FROM public.academy_lessons prev JOIN public.product_modules pm ON pm.id=prev.module_id WHERE pm.product_id=m.product_id AND prev.published AND (pm.order_index,m.order_index+prev.order_index) IS NOT NULL AND (pm.order_index,prev.order_index)<(m.order_index,l.order_index) AND NOT EXISTS(SELECT 1 FROM public.academy_progress pr WHERE pr.user_id=auth.uid() AND pr.lesson_id=prev.id))); $$;
REVOKE ALL ON FUNCTION private.academy_can_study(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION private.academy_can_study(uuid) TO authenticated;
CREATE OR REPLACE FUNCTION private.academy_get_questions(_lesson uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT private.academy_can_study(_lesson) THEN RAISE EXCEPTION 'Aula bloqueada ou acesso não autorizado'; END IF; RETURN (SELECT coalesce(jsonb_agg(jsonb_build_object('id',id,'prompt',prompt,'options',options,'kind',kind) ORDER BY random()),'[]') FROM public.academy_questions WHERE lesson_id=_lesson); END; $$;
REVOKE ALL ON FUNCTION private.academy_get_questions(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION private.academy_get_questions(uuid) TO authenticated;
CREATE OR REPLACE FUNCTION public.academy_get_questions(_lesson uuid) RETURNS jsonb LANGUAGE sql SECURITY INVOKER SET search_path=public AS $$ SELECT private.academy_get_questions(_lesson); $$;
REVOKE ALL ON FUNCTION public.academy_get_questions(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.academy_get_questions(uuid) TO authenticated;
CREATE OR REPLACE FUNCTION private.academy_submit(_lesson uuid,_answers jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE q record; total integer:=0; hits integer:=0; result jsonb:='[]'; grade numeric; good boolean; BEGIN IF auth.uid() IS NULL OR NOT private.academy_can_study(_lesson) THEN RAISE EXCEPTION 'Aula bloqueada ou acesso não autorizado'; END IF; PERFORM pg_advisory_xact_lock(hashtext(auth.uid()::text||_lesson::text)); IF (SELECT count(*) FROM public.academy_attempts WHERE user_id=auth.uid() AND lesson_id=_lesson AND created_at>now()-interval '1 minute')>=10 THEN RAISE EXCEPTION 'Aguarde antes de tentar novamente'; END IF; FOR q IN SELECT * FROM public.academy_questions WHERE lesson_id=_lesson LOOP total:=total+1; good:=coalesce((_answers->>q.id::text)::integer=q.answer_index,false); IF good THEN hits:=hits+1; END IF; result:=result||jsonb_build_array(jsonb_build_object('id',q.id,'correct',good,'answer',q.answer_index,'explanation',q.explanation)); END LOOP; IF total<3 THEN RAISE EXCEPTION 'Aula ainda sem avaliação completa'; END IF; grade:=round(100.0*hits/total,2); INSERT INTO public.academy_attempts(user_id,lesson_id,score,answers) VALUES(auth.uid(),_lesson,grade,_answers); IF grade>=80 THEN INSERT INTO public.academy_progress(user_id,lesson_id,score) VALUES(auth.uid(),_lesson,grade) ON CONFLICT(user_id,lesson_id) DO UPDATE SET score=greatest(academy_progress.score,excluded.score); INSERT INTO public.academy_xp(user_id,event_key,amount) VALUES(auth.uid(),'lesson:'||_lesson,20),(auth.uid(),'lesson-pass:'||_lesson,10) ON CONFLICT(user_id,event_key) DO NOTHING; END IF; RETURN jsonb_build_object('score',grade,'passed',grade>=80,'feedback',result); END; $$;
REVOKE ALL ON FUNCTION private.academy_submit(uuid,jsonb) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION private.academy_submit(uuid,jsonb) TO authenticated;
CREATE OR REPLACE FUNCTION public.academy_submit(_lesson uuid,_answers jsonb) RETURNS jsonb LANGUAGE sql SECURITY INVOKER SET search_path=public AS $$ SELECT private.academy_submit(_lesson,_answers); $$;
REVOKE ALL ON FUNCTION public.academy_submit(uuid,jsonb) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.academy_submit(uuid,jsonb) TO authenticated;
CREATE OR REPLACE FUNCTION private.academy_verify(_code uuid) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT jsonb_build_object('student_name',student_name,'course_title',course_title,'hours',hours,'issued_at',issued_at,'code',code,'valid',invalidated_reason IS NULL) FROM public.academy_certificates WHERE code=_code; $$;
REVOKE ALL ON FUNCTION private.academy_verify(uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION private.academy_verify(uuid) TO anon,authenticated;
GRANT USAGE ON SCHEMA private TO anon;
CREATE OR REPLACE FUNCTION public.academy_verify(_code uuid) RETURNS jsonb LANGUAGE sql SECURITY INVOKER SET search_path=public AS $$ SELECT private.academy_verify(_code); $$;
REVOKE ALL ON FUNCTION public.academy_verify(uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.academy_verify(uuid) TO anon,authenticated;